comment on column gov_repo.policy_versions.content_hash is 'SHA-256 of content_markdown. Used for QES subject_hash binding and integrity checks.';
create index idx_policy_versions_policy on gov_repo.policy_versions (policy_id, version_number);
create index idx_policy_versions_status on gov_repo.policy_versions (status);
alter table gov_repo.governance_policies add constraint fk_current_version foreign key (current_version_id) references gov_repo.policy_versions (version_id) deferrable initially deferred;
alter table gov_repo.policy_versions enable row level security;
create policy "Service role has full access to policy_versions" on gov_repo.policy_versions for all to service_role using (true) with check (true);
create policy "Org-scoped access to policy_versions" on gov_repo.policy_versions for select to authenticated using (policy_id in (select policy_id from gov_repo.governance_policies where organisation_id = (select organisation_id from gov_repo.governance_users where email = auth.email() limit 1)));
create table gov_repo.policy_mandate_mappings (mapping_id uuid primary key default uuid_generate_v4(), policy_id uuid not null references gov_repo.governance_policies(policy_id) on delete cascade, mandate_id uuid not null references gov_repo.mandates(mandate_id), coverage_level varchar(20) not null default 'partial', notes text, created_at timestamptz not null default now(), constraint policy_mandate_unique unique(policy_id,mandate_id));
alter table gov_repo.policy_mandate_mappings enable row level security;
create policy "Service role has full access to policy_mandate_mappings" on gov_repo.policy_mandate_mappings for all to service_role using (true) with check (true);
create policy "Authenticated can read policy_mandate_mappings" on gov_repo.policy_mandate_mappings for select to authenticated using (true);
create table gov_repo.risk_entries (
 risk_id uuid primary key default uuid_generate_v4(), risk_code varchar(20) not null, title varchar(255) not null, description text not null, risk_category gov_repo.risk_category not null, risk_domain varchar(50) not null, likelihood smallint not null check(likelihood between 1 and 5), impact smallint not null check(impact between 1 and 5), inherent_risk_score integer generated always as (likelihood * impact) stored, residual_risk_score integer check(residual_risk_score between 1 and 25), risk_appetite varchar(20) not null default 'tolerable' check(risk_appetite in ('acceptable','tolerable','unacceptable')), status gov_repo.risk_status not null default 'identified', owner_user_id uuid not null references gov_repo.governance_users(user_id), reviewer_user_id uuid references gov_repo.governance_users(user_id), related_agent_ids uuid[] not null default '{}', related_control_ids varchar(12)[] not null default '{}', ai_act_annex_ref varchar(100), dora_chapter_ref varchar(100), first_identified date not null default current_date, last_reviewed_date date, next_review_date date, organisation_id uuid not null references gov_repo.organisations(organisation_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence), constraint risk_entries_code_org_unique unique(risk_code,organisation_id));
comment on table gov_repo.risk_entries is 'AI governance risk register. Every risk is linked to CG-AGF controls, agents, and evidence. inherent_risk_score = likelihood × impact (computed). Max = 25 (5×5).';
comment on column gov_repo.risk_entries.related_control_ids is 'CG-AGF control IDs (e.g. CG-AG-007) associated with this risk.';
create index idx_risk_entries_org on gov_repo.risk_entries(organisation_id);
create index idx_risk_entries_status on gov_repo.risk_entries(status);
create index idx_risk_entries_score on gov_repo.risk_entries(inherent_risk_score desc);
create index idx_risk_entries_agents on gov_repo.risk_entries using gin(related_agent_ids);
create index idx_risk_entries_controls on gov_repo.risk_entries using gin(related_control_ids);
create index idx_risk_entries_owner on gov_repo.risk_entries(owner_user_id);
create trigger trg_risk_entries_updated_at before update on gov_repo.risk_entries for each row execute function gov_repo.set_updated_at();
alter table gov_repo.risk_entries enable row level security;
create policy "Service role has full access to risk_entries" on gov_repo.risk_entries for all to service_role using (true) with check (true);
create policy "Org-scoped access to risk_entries" on gov_repo.risk_entries for select to authenticated using (organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1));
create table gov_repo.risk_treatments (treatment_id uuid primary key default uuid_generate_v4(), risk_id uuid not null references gov_repo.risk_entries(risk_id) on delete cascade, treatment_type gov_repo.risk_treatment_type not null, treatment_plan text not null, controls_applied varchar(12)[] not null default '{}', target_residual integer check(target_residual between 1 and 25), due_date date not null, responsible_id uuid not null references gov_repo.governance_users(user_id), status varchar(30) not null default 'planned' check(status in ('planned','in_progress','implemented','verified','failed')), implementation_evidence uuid[] default '{}', approved_by uuid references gov_repo.governance_users(user_id), approval_date timestamptz, qes_signature_id uuid references gov_repo.qes_signatures(signature_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index idx_risk_treatments_risk on gov_repo.risk_treatments(risk_id);
create index idx_risk_treatments_status on gov_repo.risk_treatments(status);
create trigger trg_risk_treatments_updated_at before update on gov_repo.risk_treatments for each row execute function gov_repo.set_updated_at();
alter table gov_repo.risk_treatments enable row level security;
create policy "Service role has full access to risk_treatments" on gov_repo.risk_treatments for all to service_role using (true) with check (true);
create policy "Org-scoped access to risk_treatments via risk" on gov_repo.risk_treatments for select to authenticated using (risk_id in (select risk_id from gov_repo.risk_entries where organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1)));
create table gov_repo.evidence (
 evidence_id uuid primary key default uuid_generate_v4(), evidence_code varchar(20) not null, title varchar(255) not null, description text, evidence_type gov_repo.evidence_type not null, collection_method gov_repo.collection_method not null default 'manual_upload', status gov_repo.evidence_status not null default 'draft', collected_by uuid not null references gov_repo.governance_users(user_id), collected_at timestamptz not null default now(), verified_by uuid references gov_repo.governance_users(user_id), verified_at timestamptz, verification_method gov_repo.verification_method, content_hash char(64), retention_class gov_repo.retention_class not null default 'regulatory_5y', retention_until date, is_confidential boolean not null default false, classification gov_repo.classification_level not null default 'internal', organisation_id uuid not null references gov_repo.organisations(organisation_id), control_refs varchar(12)[] not null default '{}', agent_refs uuid[] not null default '{}', risk_refs uuid[] not null default '{}', chain_of_custody jsonb not null default '[]', ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint evidence_code_org_unique unique(evidence_code,organisation_id), constraint evidence_verification_consistent check ((verified_by is null and verified_at is null) or (verified_by is not null and verified_at is not null)));
comment on table gov_repo.evidence is 'Governance evidence repository. Every piece of evidence is collected, verified, linked and retained per regulatory schedule. Chain of custody is append-only JSON. Retention periods: standard_3y=3yr | regulatory_5y=5yr | dora_5y=5yr | aiact_10y=10yr | legal_hold=indefinite.';
comment on column gov_repo.evidence.chain_of_custody is 'Append-only JSON array. Schema per record: {custody_id, transferred_at, from_user_id, to_user_id, transfer_reason, record_hash}';
create or replace function gov_repo.compute_retention_until() returns trigger language plpgsql as $$ begin new.retention_until := case new.retention_class when 'standard_3y' then (new.collected_at::date + interval '3 years')::date when 'regulatory_5y' then (new.collected_at::date + interval '5 years')::date when 'dora_5y' then (new.collected_at::date + interval '5 years')::date when 'aiact_10y' then (new.collected_at::date + interval '10 years')::date when 'legal_hold' then '9999-12-31'::date else (new.collected_at::date + interval '5 years')::date end; return new; end; $$;
create trigger trg_evidence_retention before insert on gov_repo.evidence for each row execute function gov_repo.compute_retention_until();
create trigger trg_evidence_updated_at before update on gov_repo.evidence for each row execute function gov_repo.set_updated_at();
create index idx_evidence_org on gov_repo.evidence(organisation_id);
create index idx_evidence_status on gov_repo.evidence(status);
create index idx_evidence_controls on gov_repo.evidence using gin(control_refs);
create index idx_evidence_agents on gov_repo.evidence using gin(agent_refs);
create index idx_evidence_risks on gov_repo.evidence using gin(risk_refs);;
